-- =============================================================================
--  004_cuadre_kardex.sql  —  PrecisionTrucks HelpDesk
-- =============================================================================
--  Deja el kardex (movimiento_inventario) explicando el 100% del stock:
--     stock de cada insumo = entradas − salidas − ajustes
--  y cada movimiento empieza exactamente donde terminó el anterior.
--
--  1. Quita 13 movimientos artificiales del bug de entradas dobles
--     (correcciones "contada dos veces" y ajustes hechos a mano para
--     compensarlo). Durante el bug el kardex sí registraba el valor correcto;
--     lo que estaba mal era insumo.stock.
--  2. Base para Laptop: entraron 3 y no ha salido ninguna -> stock 3 (estaba en 0).
--     Teclado Inalámbrico HP: entró 1 y salió 1 (envío a CEDIS Guadalajara) -> 0.
--  3. Agrega "Inventario inicial" (59 insumos) para el stock que ya existía
--     antes de empezar a registrar movimientos.
--  4. Convierte cada hueco sin registro en un movimiento explícito (2).
--  5. Renumera id_movimiento en orden de captura.
--
--  Generado con los datos de precision_helpdesk del 2026-11-15.
--  Cada DELETE/UPDATE verifica los valores exactos: si el dato ya cambió, no
--  hace nada. Al final las tres verificaciones deben salir VACÍAS.
-- =============================================================================

SET NAMES utf8mb4;
SET @old_safe_updates := @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;

ALTER TABLE movimiento_inventario ADD COLUMN _orden DECIMAL(14,4) NULL;
UPDATE movimiento_inventario SET _orden = id_movimiento;

START TRANSACTION;

-- 1. Movimientos artificiales del bug
DELETE FROM movimiento_inventario WHERE id_movimiento = 94 AND id_insumo = 120 AND stock_anterior = 5 AND stock_nuevo = 1; -- Regulador Smartbitt AVR2200
DELETE FROM movimiento_inventario WHERE id_movimiento = 104 AND id_insumo = 128 AND stock_anterior = 1 AND stock_nuevo = 0; -- Tóner Generico Xerox 3225
DELETE FROM movimiento_inventario WHERE id_movimiento = 135 AND id_insumo = 132 AND stock_anterior = 6 AND stock_nuevo = 0; -- Base para Laptop
DELETE FROM movimiento_inventario WHERE id_movimiento = 141 AND id_insumo = 1 AND stock_anterior = 7 AND stock_nuevo = 4; -- Tóner Xerox Magenta C235
DELETE FROM movimiento_inventario WHERE id_movimiento = 142 AND id_insumo = 2 AND stock_anterior = 8 AND stock_nuevo = 4; -- Tóner Xerox Negro C235
DELETE FROM movimiento_inventario WHERE id_movimiento = 143 AND id_insumo = 18 AND stock_anterior = 7 AND stock_nuevo = 4; -- Tóner Xerox Cian C235
DELETE FROM movimiento_inventario WHERE id_movimiento = 144 AND id_insumo = 52 AND stock_anterior = 9 AND stock_nuevo = 5; -- Tóner 48A Compatible con HP M15
DELETE FROM movimiento_inventario WHERE id_movimiento = 145 AND id_insumo = 62 AND stock_anterior = 11 AND stock_nuevo = 6; -- Aire comprimido
DELETE FROM movimiento_inventario WHERE id_movimiento = 146 AND id_insumo = 120 AND stock_anterior = 1 AND stock_nuevo = 0; -- Regulador Smartbitt AVR2200
DELETE FROM movimiento_inventario WHERE id_movimiento = 147 AND id_insumo = 124 AND stock_anterior = 13 AND stock_nuevo = 7; -- Tóner compatible 85A
DELETE FROM movimiento_inventario WHERE id_movimiento = 148 AND id_insumo = 133 AND stock_anterior = 6 AND stock_nuevo = 3; -- Xerox C230 Waste Toner Bottle
DELETE FROM movimiento_inventario WHERE id_movimiento = 154 AND id_insumo = 125 AND stock_anterior = 1 AND stock_nuevo = 2; -- Tóner HP compatible 19A
DELETE FROM movimiento_inventario WHERE id_movimiento = 155 AND id_insumo = 128 AND stock_anterior = 0 AND stock_nuevo = 1; -- Tóner Generico Xerox 3225

-- 2. Stocks que quedaron mal por el bug
UPDATE insumo SET stock = 3 WHERE id_insumo = 132 AND stock = 0;  -- Base para Laptop
UPDATE insumo SET stock = 0 WHERE id_insumo = 131 AND stock = 1;  -- Teclado Inalambrico HP
UPDATE movimiento_inventario SET stock_anterior = 1, stock_nuevo = 0 WHERE id_movimiento = 123 AND id_insumo = 131 AND stock_anterior = 2;

-- 3 y 4. Inventario inicial y diferencias sin registro
INSERT INTO movimiento_inventario (id_insumo, tipo, cantidad, stock_anterior, stock_nuevo, id_empleado, motivo, fecha, fecha_registro, _orden) SELECT 1, 'Entrada', 4, 0, 4, 1, 'Inventario inicial (existencia previa al registro en el sistema)', '2026-09-01 08:00:00', NOW(), 0.0001 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM movimiento_inventario WHERE id_insumo = 1 AND motivo = 'Inventario inicial (existencia previa al registro en el sistema)' AND stock_anterior = 0); -- Tóner Xerox Magenta C235
INSERT INTO movimiento_inventario (id_insumo, tipo, cantidad, stock_anterior, stock_nuevo, id_empleado, motivo, fecha, fecha_registro, _orden) SELECT 1, 'Ajuste', 1, 2, 1, 1, 'Diferencia de inventario sin movimiento registrado (detectada al cuadrar el kardex)', '2026-11-13 17:25:03', NOW(), 136.5000 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM movimiento_inventario WHERE id_insumo = 1 AND motivo = 'Diferencia de inventario sin movimiento registrado (detectada al cuadrar el kardex)' AND stock_anterior = 2); -- Tóner Xerox Magenta C235
