-- 5. Renumerar en orden de captura (ninguna tabla referencia id_movimiento)
DROP TEMPORARY TABLE IF EXISTS _m;
CREATE TEMPORARY TABLE _m (old_id INT PRIMARY KEY, new_id INT NOT NULL)
  SELECT id_movimiento AS old_id, ROW_NUMBER() OVER (ORDER BY _orden, id_movimiento) AS new_id FROM movimiento_inventario;
UPDATE movimiento_inventario SET id_movimiento = id_movimiento + 1000000 ORDER BY id_movimiento DESC;
UPDATE movimiento_inventario t JOIN _m ON t.id_movimiento = _m.old_id + 1000000 SET t.id_movimiento = _m.new_id;
DROP TEMPORARY TABLE _m;

COMMIT;

ALTER TABLE movimiento_inventario DROP COLUMN _orden;
ALTER TABLE movimiento_inventario AUTO_INCREMENT = 1;

-- ─────────────────────────────────────────────────────────────────────────────
-- VERIFICACIÓN (las tres deben salir VACÍAS)
-- ─────────────────────────────────────────────────────────────────────────────
-- a) Cadena rota: un movimiento no empieza donde terminó el anterior
SELECT 'CADENA ROTA' AS aviso, id_insumo, id_movimiento, stock_anterior, previo
  FROM (SELECT id_insumo, id_movimiento, stock_anterior,
               LAG(stock_nuevo, 1, 0) OVER (PARTITION BY id_insumo ORDER BY id_movimiento) AS previo
          FROM movimiento_inventario) x
 WHERE stock_anterior <> previo;
-- b) Aritmética: cada movimiento suma o resta exactamente su cantidad
SELECT 'ARITMÉTICA' AS aviso, id_movimiento FROM movimiento_inventario
 WHERE stock_nuevo <> stock_anterior + IF(tipo = 'Entrada', cantidad, -cantidad);
-- c) Stock distinto de entradas − salidas − ajustes
SELECT 'NO CUADRA' AS aviso, i.id_insumo, i.nombre, i.stock,
       COALESCE(SUM(IF(m.tipo = 'Entrada', m.cantidad, -m.cantidad)), 0) AS kardex
  FROM insumo i LEFT JOIN movimiento_inventario m ON m.id_insumo = i.id_insumo
 GROUP BY i.id_insumo, i.nombre, i.stock
HAVING i.stock <> kardex;

SET SQL_SAFE_UPDATES = @old_safe_updates;
SELECT 'Migración 004 aplicada: el kardex cuadra con el stock' AS resultado;
